inputs.script:
const table = base.getTable("Email Account Bulk Controls");
const { recordId } = input.config();

if (!recordId) {
  throw new Error("Missing recordId input variable");
}

const record = await table.selectRecordAsync(recordId);

if (!record) {
  throw new Error(`Bulk control request ${recordId} was not found`);
}

if (!record.getCellValue("Approve")) {
  throw new Error("Approve must be checked before this request can run");
}

const updates = {
  "Status": { name: "Processing" },
  "Error": null
};

if (!record.getCellValueAsString("Request").trim()) {
  const client =
    record.getCellValueAsString("Client").trim() || "Client";

  const action =
    record.getCellValueAsString("Action").trim() || "Bulk Update";

  const timestamp = new Date().toLocaleString("en-US", {
    timeZone: "America/New_York",
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit"
  });

  updates["Request"] = `${client} — ${action} — ${timestamp}`;
}

await table.updateRecordAsync(recordId, updates);

const response = await fetch(
  "https://n8n.dulcy.io/webhook/REDACTED_PATH",
  {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({ recordId })
  }
);

if (!response.ok) {
  const message = (await response.text()).slice(0, 10000);

  await table.updateRecordAsync(recordId, {
    "Status": { name: "Failed" },
    "Error": `Webhook ${response.status}: ${message}`
  });

  throw new Error(`n8n webhook failed (${response.status})`);
}
